@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap');

/* ─── CSS Variables ─── */
:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-secondary: #6B6560;
  --accent-warm: #C17A53;
  --accent-sage: #8A9A7B;
  --accent-sand: #D4C4A8;
  --border: #E5E0D8;
  --white: #FFFFFF;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --transition: 0.25s ease;
}

/* ─── Reset ─── */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* ─── Typography ─── */
h1, h2, h3, h4 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

/* ─── Layout ─── */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container {
    padding: 0 48px;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 64px;
  }
}

/* ─── Header / Navigation ─── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  padding: 20px 0;
  transition: background var(--transition), box-shadow var(--transition);
}

.site-header.scrolled {
  background: rgba(245, 242, 237, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  z-index: 110;
}

.desktop-nav {
  display: none;
}

.desktop-nav a {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  margin-left: 32px;
  position: relative;
  transition: opacity var(--transition);
}

.desktop-nav a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width var(--transition);
}

.desktop-nav a:hover::after,
.desktop-nav a.active::after {
  width: 100%;
}

.desktop-nav a:hover {
  opacity: 0.7;
}

@media (min-width: 768px) {
  .desktop-nav {
    display: flex;
  }
}

/* ─── Mobile Menu Toggle ─── */
.menu-toggle {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  gap: 6px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 110;
  padding: 0;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  border-radius: 1px;
  transition: transform 0.3s ease, opacity 0.3s ease;
  transform-origin: center;
}

.menu-toggle[aria-expanded="true"] span:first-child {
  transform: translateY(7.5px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:last-child {
  transform: translateY(-7.5px) rotate(-45deg);
}

@media (min-width: 768px) {
  .menu-toggle {
    display: none;
  }
}

/* ─── Mobile Overlay ─── */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 90;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.mobile-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 600;
  margin: 12px 0;
  opacity: 0;
  transform: translateY(12px);
  transition: opacity 0.4s ease, transform 0.4s ease, color var(--transition);
}

.mobile-overlay.open a {
  opacity: 1;
  transform: translateY(0);
}

.mobile-overlay a:nth-child(1) { transition-delay: 0.08s; }
.mobile-overlay a:nth-child(2) { transition-delay: 0.14s; }
.mobile-overlay a:nth-child(3) { transition-delay: 0.20s; }
.mobile-overlay a:nth-child(4) { transition-delay: 0.26s; }
.mobile-overlay a:nth-child(5) { transition-delay: 0.32s; }

.mobile-overlay a:hover {
  color: var(--accent-warm);
}

/* ─── Main Content Padding ─── */
main {
  padding-top: 72px;
}

/* ─── Hero ─── */
.hero {
  padding: 80px 0 64px;
}

.hero h1 {
  font-size: clamp(2.5rem, 6vw, 5rem);
  max-width: 900px;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

/* ─── Media Showcase ─── */
.media-showcase {
  padding: 32px 0 80px;
}

.media-triptych {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 768px) {
  .media-triptych {
    grid-template-columns: 1.2fr 0.8fr 1fr;
    gap: 20px;
  }
}

.media-block {
  aspect-ratio: 4 / 3;
  border-radius: 4px;
  overflow: hidden;
}

.media-block.terracotta { background: #C17A53; }
.media-block.sage { background: #8A9A7B; }
.media-block.sand { background: #D4C4A8; }

/* ─── Client Marquee ─── */
.marquee-section {
  padding: 48px 0 80px;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  will-change: transform;
  padding: 14px 0;
}

.marquee-track {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  animation: marquee-left 40s linear infinite;
}

.marquee-row.reverse .marquee-track {
  animation: marquee-right 45s linear infinite;
}

.marquee-row:nth-child(3) .marquee-track {
  animation: marquee-left 50s linear infinite;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3.5vw, 2.75rem);
  font-weight: 500;
  color: var(--text);
  opacity: 0.35;
  padding: 0 28px;
  letter-spacing: -0.01em;
  user-select: none;
}

.marquee-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text);
  opacity: 0.2;
  flex-shrink: 0;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    animation: none !important;
  }
}

/* ─── About Section ─── */
.about-section {
  padding: 80px 0 120px;
}

.about-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-secondary);
  margin-bottom: 32px;
}

.about-text {
  font-size: 1.125rem;
  line-height: 1.75;
  max-width: 720px;
  color: var(--text);
}

.about-text p + p {
  margin-top: 1.5em;
}

/* ─── Founder Letter ─── */
.letter-section {
  padding: 64px 0 120px;
}

.letter-container {
  max-width: 680px;
  margin: 0 auto;
}

.letter-header {
  margin-bottom: 56px;
}

.letter-header h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 12px;
}

.letter-meta {
  font-size: 0.875rem;
  color: var(--text-secondary);
  font-style: italic;
  font-family: var(--font-serif);
}

.letter-body {
  font-size: 1.125rem;
  line-height: 1.85;
  color: var(--text);
}

.letter-body p + p {
  margin-top: 1.6em;
}

.letter-body p:first-child::first-letter {
  font-family: var(--font-serif);
  font-size: 4.5rem;
  float: left;
  line-height: 0.8;
  padding-right: 12px;
  padding-top: 6px;
  font-weight: 600;
}

.letter-signoff {
  margin-top: 56px;
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 600;
  font-style: italic;
}

/* ─── Services ─── */
.philosophy-section {
  padding: 64px 0 80px;
}

.philosophy-section h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 40px;
}

.philosophy-heading {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-weight: 600;
  margin-bottom: 24px;
}

.philosophy-text {
  font-size: 1.125rem;
  line-height: 1.75;
  max-width: 720px;
}

.divider {
  height: 1px;
  background: var(--border);
  margin: 0 auto;
  max-width: 1280px;
  padding: 0 24px;
}

.services-detail {
  padding: 80px 0 120px;
}

.services-detail h2 {
  font-size: clamp(1.5rem, 3.5vw, 2.25rem);
  margin-bottom: 56px;
  max-width: 600px;
}

.service-item {
  margin-bottom: 48px;
  max-width: 720px;
}

.service-item:last-child {
  margin-bottom: 0;
}

.service-item h3 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 12px;
  font-family: var(--font-sans);
  letter-spacing: 0;
}

.service-item p {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* ─── Clients ─── */
.clients-section {
  padding: 64px 0 120px;
}

.clients-section h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 8px;
}

.clients-subhead {
  font-size: 1.125rem;
  color: var(--text-secondary);
  margin-bottom: 64px;
}

.clients-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px 32px;
}

@media (min-width: 640px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.6;
  color: var(--text-secondary);
}

/* ─── Contact ─── */
.contact-section {
  min-height: calc(100dvh - 72px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 64px 24px;
}

.contact-section h1 {
  font-size: clamp(4rem, 14vw, 12rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
  margin-bottom: 48px;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

@media (min-width: 640px) {
  .contact-links {
    flex-direction: row;
    gap: 40px;
  }
}

.contact-links a {
  font-size: 1.125rem;
  font-weight: 500;
  position: relative;
  transition: color var(--transition);
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--accent-warm);
  transition: width var(--transition);
}

.contact-links a:hover {
  color: var(--accent-warm);
}

.contact-links a:hover::after {
  width: 100%;
}

/* ─── Footer ─── */
.site-footer {
  padding: 32px 0;
  border-top: 1px solid var(--border);
}

.site-footer .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-copy {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

/* ─── Utilities ─── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

(function () {
  'use strict';

  // ─── Header scroll state ───
  const header = document.querySelector('.site-header');
  if (header) {
    const onScroll = () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }

  // ─── Mobile menu toggle ───
  const toggle = document.querySelector('.menu-toggle');
  const overlay = document.querySelector('.mobile-overlay');

  if (toggle && overlay) {
    const openMenu = () => {
      toggle.setAttribute('aria-expanded', 'true');
      overlay.classList.add('open');
      document.body.style.overflow = 'hidden';
    };

    const closeMenu = () => {
      toggle.setAttribute('aria-expanded', 'false');
      overlay.classList.remove('open');
      document.body.style.overflow = '';
    };

    toggle.addEventListener('click', () => {
      const isOpen = toggle.getAttribute('aria-expanded') === 'true';
      isOpen ? closeMenu() : openMenu();
    });

    overlay.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', closeMenu);
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && toggle.getAttribute('aria-expanded') === 'true') {
        closeMenu();
      }
    });
  }

  // ─── Marquee: duplicate tracks for seamless loop ───
  document.querySelectorAll('.marquee-row').forEach(row => {
    const track = row.querySelector('.marquee-track');
    if (!track) return;
    // Clone the track and append it so the content repeats seamlessly
    const clone = track.cloneNode(true);
    row.appendChild(clone);
  });
})();
